        instruction("shlq", "$16, %r8");
        instruction("orq", "%rax, %r8");
        instruction("jne", nan_a);
        output_ << check_b << ":\n";
        instruction("movq", "%r11, %rcx");
        instruction("shrq", "$48, %rcx");
        instruction("andl", "$32767, %ecx");
        instruction("movq", "%rcx, " + f128_scratch(function, 104));
        instruction("cmpl", "$32767, %ecx");
        instruction("jne", classified);
        instruction("movq", "%r11, %r8");
        instruction("shlq", "$16, %r8");
        instruction("orq", "%r10, %r8");
        instruction("jne", nan_b);
        output_ << classified << ":\n";
        instruction("movq", "%rdx, %r8");
        instruction("xorq", "%r11, %r8");
        instruction("shrq", "$63, %r8");
        instruction("shlq", "$63, %r8");
        instruction("movq", "%r8, " + f128_scratch(function, 112));

        instruction("cmpq", "$32767, " + f128_scratch(function, 96));
        instruction("jne", b_finite);
        instruction("movq", f128_scratch(function, 24) + ", %r8");
        instruction("btrq", "$63, %r8");
        instruction("orq", f128_scratch(function, 16) + ", %r8");
        instruction("je", invalid);
        instruction("jmp", infinity);
        output_ << b_finite << ":\n";
        instruction("cmpq", "$32767, " + f128_scratch(function, 104));
        instruction("jne", finite);
        instruction("movq", f128_scratch(function, 8) + ", %r8");
        instruction("btrq", "$63, %r8");
        instruction("orq", f128_scratch(function, 0) + ", %r8");
        instruction("je", invalid);
        instruction("jmp", infinity);
        output_ << finite << ":\n";
        instruction("movq", f128_scratch(function, 8) + ", %r8");
        instruction("btrq", "$63, %r8");
        instruction("orq", f128_scratch(function, 0) + ", %r8");
        instruction("je", zero);
        instruction("movq", f128_scratch(function, 24) + ", %r8");
        instruction("btrq", "$63, %r8");
        instruction("orq", f128_scratch(function, 16) + ", %r8");
        instruction("je", zero);

        emit_f128_unpack_normalized(function, 0, 32, 96, "mul.a");
        emit_f128_unpack_normalized(function, 16, 48, 104, "mul.b");
        instruction("movq", f128_scratch(function, 96) + ", %rax");
        instruction("addq", f128_scratch(function, 104) + ", %rax");
        instruction("movq", "%rax, " + f128_scratch(function, 128));

        instruction("movq", f128_scratch(function, 32) + ", %rax");
        instruction("mulq", f128_scratch(function, 48));
        instruction("movq", "%rax, " + f128_scratch(function, 64));
        instruction("movq", "%rdx, " + f128_scratch(function, 72));
        instruction("movq", "$0, " + f128_scratch(function, 80));
        instruction("movq", "$0, " + f128_scratch(function, 88));
        instruction("movq", f128_scratch(function, 32) + ", %rax");
        instruction("mulq", f128_scratch(function, 56));
        instruction("addq", "%rax, " + f128_scratch(function, 72));
        instruction("adcq", "%rdx, " + f128_scratch(function, 80));
        instruction("adcq", "$0, " + f128_scratch(function, 88));
