        instruction("adcq", "%rdx, " + f128_scratch(function, 80));
        instruction("adcq", "$0, " + f128_scratch(function, 88));
        instruction("movq", f128_scratch(function, 40) + ", %rax");
        instruction("mulq", f128_scratch(function, 56));
        instruction("addq", "%rax, " + f128_scratch(function, 80));
        instruction("adcq", "%rdx, " + f128_scratch(function, 88));

        instruction("btq", "$33, " + f128_scratch(function, 88));
        instruction("jnc", lower_product);
        instruction("addq", "$1, " + f128_scratch(function, 128));
        instruction("movl", "$46, %ecx");
