        instruction("movq", "%r11, %rcx");
        instruction("shrq", "$48, %rcx");
        instruction("andl", "$32767, %ecx");
        instruction("movq", "%rcx, " + f128_scratch(function, 104));
        instruction("cmpl", "$32767, %ecx");
        instruction("jne", classified);
        instruction("movq", "%r11, %r8");
        instruction("shlq", "$16, %r8");
        instruction("orq", "%r10, %r8");
        instruction("jne", nan_b);
        output_ << classified << ":\n";
        instruction("movq", "%rdx, %r8");
        instruction("xorq", "%r11, %r8");
        instruction("shrq", "$63, %r8");
        instruction("shlq", "$63, %r8");
        instruction("movq", "%r8, " + f128_scratch(function, 112));

        instruction("cmpq", "$32767, " + f128_scratch(function, 96));
        instruction("jne", a_finite);
        instruction("cmpq", "$32767, " + f128_scratch(function, 104));
        instruction("je", invalid);
        instruction("jmp", infinity);
        output_ << a_finite << ":\n";
        instruction("cmpq", "$32767, " + f128_scratch(function, 104));
        instruction("jne", b_finite);
        instruction("jmp", zero);
        output_ << b_finite << ":\n";
        instruction("movq", f128_scratch(function, 24) + ", %r8");
        instruction("btrq", "$63, %r8");
        instruction("orq", f128_scratch(function, 16) + ", %r8");
        instruction("jne", nonzero_divisor);
        instruction("movq", f128_scratch(function, 8) + ", %r8");
        instruction("btrq", "$63, %r8");
        instruction("orq", f128_scratch(function, 0) + ", %r8");
        instruction("je", invalid);
        instruction("jmp", infinity);
        output_ << nonzero_divisor << ":\n";
        instruction("movq", f128_scratch(function, 8) + ", %r8");
        instruction("btrq", "$63, %r8");
        instruction("orq", f128_scratch(function, 0) + ", %r8");
        instruction("je", zero);
