        emit_f128_unpack_normalized(function, 0, 32, 96, "div.a");
        emit_f128_unpack_normalized(function, 16, 48, 104, "div.b");
        instruction("movq", f128_scratch(function, 96) + ", %rax");
        instruction("subq", f128_scratch(function, 104) + ", %rax");
        instruction("movq", "%rax, " + f128_scratch(function, 128));
        instruction("movq", "$0, " + f128_scratch(function, 64));
        instruction("movabsq", "$2251799813685248, %rax");
        instruction("movq", "%rax, " + f128_scratch(function, 72));

        instruction("movq", f128_scratch(function, 40) + ", %rax");
        instruction("cmpq", f128_scratch(function, 56) + ", %rax");
        instruction("jb", less);
