        instruction("movq", f128_scratch(function, 32) + ", %rax");
        instruction("cmpq", f128_scratch(function, 48) + ", %rax");
        instruction("jb", less);
        instruction("jmp", remainder_ready);
        output_ << less << ":\n";
        instruction("subq", "$1, " + f128_scratch(function, 128));
        instruction("shlq", "$1, " + f128_scratch(function, 32));
        instruction("rclq", "$1, " + f128_scratch(function, 40));
        output_ << remainder_ready << ":\n";
        instruction("movq", f128_scratch(function, 32) + ", %rax");
        instruction("movq", f128_scratch(function, 40) + ", %rdx");
        instruction("subq", f128_scratch(function, 48) + ", %rax");
        instruction("sbbq", f128_scratch(function, 56) + ", %rdx");
        instruction("movq", "%rax, " + f128_scratch(function, 32));
        instruction("movq", "%rdx, " + f128_scratch(function, 40));
        instruction("movl", "$114, %ecx");
        output_ << loop << ":\n";
        instruction("shlq", "$1, " + f128_scratch(function, 32));
        instruction("rclq", "$1, " + f128_scratch(function, 40));
        instruction("movq", f128_scratch(function, 40) + ", %rax");
        instruction("cmpq", f128_scratch(function, 56) + ", %rax");
        instruction("jb", next_bit);
        instruction("ja", compare_low);
        instruction("movq", f128_scratch(function, 32) + ", %rax");
